INSERT IGNORE INTO blog_posts (id, slug, title, category, date, readTime, author, authorAvatar, image, excerpt, content) VALUES ('dtcp-rera-buyer-guide', 'guide-to-buying-dtcp-rera-approved-layout-plots-in-thanjavur', 'Guide to Buying DTCP & RERA Approved Layout Plots in Thanjavur', 'Legal & Patta', '10 Aug 2026', '5 min read', 'Thanjai Legal Advisory', 'https://ui-avatars.com/api/?name=Thanjai+Legal&background=2A1808&color=F8F4EC', 'https://images.unsplash.com/photo-1524813686514-a57563d77965?auto=format&fit=crop&w=1200&q=80', 'Essential checklist for verifying Patta title deeds, DTCP approval numbers, and revenue records before purchasing residential plots in Thanjavur and Kaveri Delta.', '<p class="blog-lead">Purchasing real estate in Tamil Nadu is one of the safest multi-generational investments when backed by verified legal Patta titles and DTCP/RERA approvals. Here is what every buyer must check before committing.</p>
INSERT IGNORE INTO blog_posts (id, slug, title, category, date, readTime, author, authorAvatar, image, excerpt, content) VALUES ('kaveri-farmland-investment', 'the-rising-appreciation-of-kaveri-riverfront-agricultural-farmlands', 'The Rising Appreciation of Kaveri Riverfront Agricultural Farmlands', 'Investment', '28 Jul 2026', '6 min read', 'Senior Land Specialist', 'https://ui-avatars.com/api/?name=Arun+Prakash&background=2A1808&color=F8F4EC', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80', 'Why fertile agricultural land in Kumbakonam, Papanasam, and Kaveri delta belt remains a high-yielding, multi-generational wealth asset for investors.', '<p class="blog-lead">Agricultural farmlands along the Kaveri river basin in Kumbakonam and Thanjavur continue to attract high-net-worth investors seeking passive yield, organic farming retreats, and long-term land value appreciation.</p>
INSERT IGNORE INTO blog_posts (id, slug, title, category, date, readTime, author, authorAvatar, image, excerpt, content) VALUES ('contemporary-villas-architecture', 'modern-villa-architecture-blending-dravidian-courtyards-with-contemporary-luxury', 'Modern Villa Architecture: Blending Dravidian Courtyards with Contemporary Luxury', 'Architecture', '15 Jul 2026', '4 min read', 'Architectural Desk', 'https://ui-avatars.com/api/?name=Design+Desk&background=2A1808&color=F8F4EC', 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80', 'Exploring modern luxury villas in Chennai and Thanjavur featuring open-air courtyards, VRV climate control, double-height ceilings, and lush tropical courtyards.', '<p class="blog-lead">Traditional South Indian courtyard architecture (Thinnai & Mutram) is experiencing a revival in high-end villa designs across Chennai, Trichy, and Thanjavur.</p>
INSERT IGNORE INTO blog_posts (id, slug, title, category, date, readTime, author, authorAvatar, image, excerpt, content) VALUES ('central-tn-commercial-hubs', 'investing-in-central-tamil-nadu-trichy-thanjavur-commercial-corridors', 'Investing in Central Tamil Nadu: Trichy & Thanjavur Commercial Corridors', 'Market Guide', '30 Jun 2026', '5 min read', 'Market Intelligence', 'https://ui-avatars.com/api/?name=Thanjai+Research&background=2A1808&color=F8F4EC', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80', 'Commercial real estate growth analysis along Thanjavur New Bus Stand, Medical College Road, and Trichy Thillai Nagar high streets.', '<p class="blog-lead">Central Tamil Nadu cities like Trichy and Thanjavur are benefiting from infrastructure expansions including airport upgrades and NH highway widening, fueling 12-15% annual commercial property appreciation.</p>
INSERT IGNORE INTO blog_posts (id, slug, title, category, date, readTime, author, authorAvatar, image, excerpt, content) VALUES ('nri-property-buying-guide', 'nri-real-estate-guide-purchasing-property-in-tamil-nadu-seamlessly', 'NRI Real Estate Guide: Purchasing Property in Tamil Nadu Seamlessly', 'NRI Guide', '12 Jun 2026', '7 min read', 'NRI Advisory Services', 'https://ui-avatars.com/api/?name=NRI+Desk&background=2A1808&color=F8F4EC', 'https://images.unsplash.com/photo-1613977257363-707ba9348227?auto=format&fit=crop&w=1200&q=80', 'Essential checklist for non-resident Indians acquiring luxury villas, farm plots, and commercial assets in Tamil Nadu with remote legal execution.', '<p class="blog-lead">Non-Resident Indians (NRIs) can freely acquire residential and commercial properties in India under RBI FEMA guidelines without requiring prior RBI permission.</p>
